%[text] %[text:anchor:H_C6B6CB28] ## Types of filters
%[text] There are many different types of filters to be used in many different scenarios. In the following sections, you will learn about some of the most common ones and how they can be applied.
%[text] *Your goal as you work through the following sections will be to use these filters to isolate the bird chirps from the background noise in the birdsong signal.*
%%
%[text] %[text:anchor:H_52BF8687] ### Highpass filters
%[text] Highpass filters, as the name suggests, keep the high-frequency components of a signal, which are higher than the specified *passband frequency*, while *attenuating*, or limiting the strength of, the low-frequency components which are lower than the passband frequency. 
%[text] ![](text:image:8889) **Try**. Use the controls below to apply highpass filters with different passband frequencies to the birdsong data and observe the results by visualizing the filtered signal in the different domains and comparing the filtered recording to the unfiltered recording. Keep in mind the goal of isolating the bird chirps from the background noise.
PassbandFrequency = 0.1 * 1000; %[control:slider:9aee]{"position":[21,24]}
VisualizationDomain = "time domain"; %[control:dropdown:2ac2]{"position":[23,36]}
  %[control:button:3ca6]{"position":[1,2]}

HighpassSignal = highpass(Signal, PassbandFrequency, SamplingFrequency);

if VisualizationDomain == 'time domain'
    plot((1 / SamplingFrequency) * (1:length(HighpassSignal)), HighpassSignal);
    title("Filtered Birdsong Signal");
    xlabel("Time (Seconds)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'FFT'
    y = fft(HighpassSignal);
    p2 = abs(y / length(HighpassSignal));
    p1 = p2(1:(length(HighpassSignal)/2)+1);
    p1(2:end-1) = 2 * p1(2:end-1);
    f = SamplingFrequency / length(HighpassSignal) * (0:(length(HighpassSignal) / 2));
    plot(f/1000, p1);
    title("FFT of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'power spectrum'
    [p, f] = pspectrum(HighpassSignal, SamplingFrequency);
    p = 10 * log10(p);
    plot(f/1000, p);
    title("Power Spectrum of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Power Spectrum (dB)");
elseif VisualizationDomain == 'spectrogram'
    pspectrum(HighpassSignal, SamplingFrequency, 'spectrogram');
    title("Spectrogram of Filtered Birdsong Signal");
end
%%
  %[control:button:2ca5]{"position":[1,2]}

try
    HighpassPlayer = audioplayer(HighpassSignal, SamplingFrequency);
    pspectrum(HighpassSignal, SamplingFrequency, 'spectrogram');
    hold on;
    title("Spectrogram of Filtered Birdsong Signal");
    Line = xline(0, LineWidth=2, SeriesIndex=7);
    play(HighpassPlayer);
    pause(0.1);
    for i = 1:100
        Line.Value = i * 0.1;
        pause(0.1);
    end
    hold off;
catch ErrorMessage
    if ErrorMessage.identifier == "MATLAB:UndefinedFunction"
        disp("Visualize the filtered signal before playing the recording");
    end
end
%%
  %[control:button:6bc7]{"position":[1,2]}

UnfilteredPlayer = audioplayer(Signal, SamplingFrequency);
pspectrum(Signal, SamplingFrequency, 'spectrogram');
hold on;
title("Spectrogram of Unfiltered Birdsong Signal");
Line = xline(0, LineWidth=2, SeriesIndex=7);
play(UnfilteredPlayer);
pause(0.1);
for i = 1:100
    Line.Value = i * 0.1;
    pause(0.1);
end
hold off;
%%
%[text] %[text:anchor:H_15DB4EBF] ### Lowpass filters
%[text] Lowpass filters, on the other hand, keep the low-frequency components of a signal while attenuating the high-frequency components.
%[text] ![](text:image:2497) **Try**. Use the controls below to apply lowpass filters with different passband frequencies to the birdsong data and observe the results by visualizing the filtered signal in the different domains and comparing the filtered recording to the unfiltered recording. Keep in mind the goal of isolating the bird chirps from the background noise.
PassbandFrequency = 0.1 * 1000; %[control:slider:7640]{"position":[21,24]}
VisualizationDomain = "time domain"; %[control:dropdown:84f1]{"position":[23,36]}
  %[control:button:4de3]{"position":[1,2]}

LowpassSignal = lowpass(Signal, PassbandFrequency, SamplingFrequency);

if VisualizationDomain == 'time domain'
    plot((1 / SamplingFrequency) * (1:length(LowpassSignal)), LowpassSignal);
    title("Filtered Birdsong Signal");
    xlabel("Time (Seconds)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'FFT'
    y = fft(LowpassSignal);
    p2 = abs(y / length(LowpassSignal));
    p1 = p2(1:(length(LowpassSignal)/2)+1);
    p1(2:end-1) = 2 * p1(2:end-1);
    f = SamplingFrequency / length(LowpassSignal) * (0:(length(LowpassSignal) / 2));
    plot(f/1000, p1);
    title("FFT of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'power spectrum'
    [p, f] = pspectrum(LowpassSignal, SamplingFrequency);
    p = 10 * log10(p);
    plot(f/1000, p);
    title("Power Spectrum of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Power Spectrum (dB)");
elseif VisualizationDomain == 'spectrogram'
    pspectrum(LowpassSignal, SamplingFrequency, 'spectrogram');
    title("Spectrogram of Filtered Birdsong Signal");
end
%%
  %[control:button:4287]{"position":[1,2]}

try
    LowpassPlayer = audioplayer(LowpassSignal, SamplingFrequency);
    pspectrum(LowpassSignal, SamplingFrequency, 'spectrogram');
    hold on;
    title("Spectrogram of Filtered Birdsong Signal");
    Line = xline(0, LineWidth=2, SeriesIndex=7);
    play(LowpassPlayer);
    pause(0.1);
    for i = 1:100
        Line.Value = i * 0.1;
        pause(0.1);
    end
    hold off;
catch ErrorMessage
    if ErrorMessage.identifier == "MATLAB:UndefinedFunction"
        disp("Visualize the filtered signal before playing the recording");
    end
end
%%
  %[control:button:8fc7]{"position":[1,2]}

UnfilteredPlayer = audioplayer(Signal, SamplingFrequency);
pspectrum(Signal, SamplingFrequency, 'spectrogram');
hold on;
title("Spectrogram of Unfiltered Birdsong Signal");
Line = xline(0, LineWidth=2, SeriesIndex=7);
play(UnfilteredPlayer);
pause(0.1);
for i = 1:100
    Line.Value = i * 0.1;
    pause(0.1);
end
hold off;
%[text] ![](text:image:6532) **Reflect**. How successful have you been in isolating the bird chirps from the background noise using highpass and lowpass filters? If you have struggled, you may be interested in the next type of filter...
%%
%[text] %[text:anchor:H_90AAD019] ### Bandpass filters
%[text] Bandpass filters allow components within a specified range of frequencies to pass through, and attenuate all other components. These filters require two parameters: the upper and lower passband frequency limits to define the range of acceptable frequencies to pass through the filter.
%[text] ![](text:image:5fc7) **Try**. Use the controls below to apply bandpass filters with different frequency ranges to the birdsong data and observe the results by visualizing the filtered signal in the different domains and comparing the filtered recording to the unfiltered recording. Keep in mind the goal of isolating the bird chirps from the background noise.
%[text] ![](text:image:2452) **Pro-tip**. You won't be using it in this activity, but there is another type of filter called a *bandstop filter* that can be useful in many applications. As its name suggests, it does the opposite of a bandpass filter - while a bandpass filter allows frequencies in the specified range to *pass* through, a bandstop filter *stops* frequencies in the specified range from passing through.
LowerPassbandFrequency = 0.1 * 1000; %[control:slider:571f]{"position":[26,29]}
UpperPassbandFrequency = 0.1 * 1000; %[control:slider:187c]{"position":[26,29]}
VisualizationDomain = "time domain"; %[control:dropdown:2d6d]{"position":[23,36]}
  %[control:button:455c]{"position":[1,2]}

try
    BandpassSignal = bandpass(Signal, [LowerPassbandFrequency UpperPassbandFrequency], SamplingFrequency);
catch
    disp("Make sure your upper passband frequency is greater than your lower passband frequency.");
    return;
end

if VisualizationDomain == 'time domain'
    plot((1 / SamplingFrequency) * (1:length(BandpassSignal)), BandpassSignal);
    title("Filtered Birdsong Signal");
    xlabel("Time (Seconds)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'FFT'
    y = fft(BandpassSignal);
    p2 = abs(y / length(BandpassSignal));
    p1 = p2(1:(length(BandpassSignal)/2)+1);
    p1(2:end-1) = 2 * p1(2:end-1);
    f = SamplingFrequency / length(BandpassSignal) * (0:(length(BandpassSignal) / 2));
    plot(f/1000, p1);
    title("FFT of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Amplitude");
elseif VisualizationDomain == 'power spectrum'
    [p, f] = pspectrum(BandpassSignal, SamplingFrequency);
    p = 10 * log10(p);
    plot(f/1000, p);
    title("Power Spectrum of Filtered Birdsong Signal");
    xlabel("Frequency (kHz)");
    ylabel("Power Spectrum (dB)");
elseif VisualizationDomain == 'spectrogram'
    pspectrum(BandpassSignal, SamplingFrequency, 'spectrogram');
    title("Spectrogram of Filtered Birdsong Signal");
end
%%
  %[control:button:69af]{"position":[1,2]}

try
    BandpassPlayer = audioplayer(BandpassSignal, SamplingFrequency);
    pspectrum(BandpassSignal, SamplingFrequency, 'spectrogram');
    hold on;
    title("Spectrogram of Filtered Birdsong Signal");
    Line = xline(0, LineWidth=2, SeriesIndex=7);
    play(BandpassPlayer);
    pause(0.1);
    for i = 1:100
        Line.Value = i * 0.1;
        pause(0.1);
    end
    hold off;
catch ErrorMessage
    if ErrorMessage.identifier == "MATLAB:UndefinedFunction"
        disp("Visualize the filtered signal before playing the recording");
    end
end
%%
  %[control:button:09ee]{"position":[1,2]}

UnfilteredPlayer = audioplayer(Signal, SamplingFrequency);
pspectrum(Signal, SamplingFrequency, 'spectrogram');
hold on;
title("Spectrogram of Unfiltered Birdsong Signal");
Line = xline(0, LineWidth=2, SeriesIndex=7);
play(UnfilteredPlayer);
pause(0.1);
for i = 1:100
    Line.Value = i * 0.1;
    pause(0.1);
end
hold off;
%%
%[text] ![](text:image:5a84) **Exercise 3.** Once you are satisfied that your filter has filtered out as much background noise as possible while keeping the bird chirps, use the button below to submit your solution.
  %[control:button:5bdd]{"position":[1,2]}
CheckExercise3(LowerPassbandFrequency/1000, UpperPassbandFrequency/1000);
%[text] ![](text:image:5a46) **Reflect**. In what other scenarios could you imagine these filtering techniques being useful?
